<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Secretaria');

$tipo = $_GET['tipo'] ?? $_POST['tipo'] ?? 'professor_disciplina';
$tipos = ['professor_disciplina' => 'Professor e disciplina', 'turma_disciplina' => 'Turma, disciplina e professor', 'horario' => 'Horários'];
if (!isset($tipos[$tipo])) { $tipo = 'professor_disciplina'; }
$mensagem = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $id = intval($_POST['id'] ?? 0);
    if (isset($_POST['remover']) && $id > 0) {
        $tabela = $tipo === 'professor_disciplina' ? 'professor_disciplina' : ($tipo === 'turma_disciplina' ? 'turma_disciplina' : 'horario');
        $chave = $tipo === 'professor_disciplina' ? 'id_professor_disciplina' : ($tipo === 'turma_disciplina' ? 'id_turma_disciplina' : 'id_horario');
        $stmt = $conexao->prepare("DELETE FROM $tabela WHERE $chave=?");
        $stmt->bind_param('i', $id);
        $ok = $stmt->execute();
        $stmt->close();
        $mensagem = $ok ? '<div class="sucesso">Vínculo removido com sucesso.</div>' : '<div class="erro">Não foi possível remover o vínculo.</div>';
    } elseif ($tipo === 'professor_disciplina') {
        $professor = intval($_POST['id_professor'] ?? 0); $disciplina = intval($_POST['id_disciplina'] ?? 0);
        if ($professor > 0 && $disciplina > 0) {
            $stmt = $conexao->prepare('SELECT COUNT(*) AS total FROM professor_disciplina WHERE id_professor=? AND id_disciplina=?'); $stmt->bind_param('ii', $professor, $disciplina); $stmt->execute(); $existe=(int)$stmt->get_result()->fetch_assoc()['total']>0; $stmt->close();
            if ($existe) { $mensagem='<div class="aviso">Esse vínculo já existe.</div>'; } else { $stmt=$conexao->prepare('INSERT INTO professor_disciplina (id_professor,id_disciplina) VALUES (?,?)');$stmt->bind_param('ii',$professor,$disciplina);$ok=$stmt->execute();$stmt->close();$mensagem=$ok?'<div class="sucesso">Vínculo criado com sucesso.</div>':'<div class="erro">Não foi possível criar o vínculo.</div>'; }
        }
    } elseif ($tipo === 'turma_disciplina') {
        $turma=intval($_POST['id_turma']??0);$disciplina=intval($_POST['id_disciplina']??0);$professor=intval($_POST['id_professor']??0);
        if($turma>0&&$disciplina>0&&$professor>0){$stmt=$conexao->prepare('SELECT COUNT(*) AS total FROM turma_disciplina WHERE id_turma=? AND id_disciplina=? AND id_professor=?');$stmt->bind_param('iii',$turma,$disciplina,$professor);$stmt->execute();$existe=(int)$stmt->get_result()->fetch_assoc()['total']>0;$stmt->close();if($existe){$mensagem='<div class="aviso">Esse vínculo já existe.</div>';}else{$stmt=$conexao->prepare('INSERT INTO turma_disciplina(id_turma,id_disciplina,id_professor) VALUES(?,?,?)');$stmt->bind_param('iii',$turma,$disciplina,$professor);$ok=$stmt->execute();$stmt->close();$mensagem=$ok?'<div class="sucesso">Vínculo criado com sucesso.</div>':'<div class="erro">Não foi possível criar o vínculo.</div>';}}
    } else {
        $vinculo=intval($_POST['id_turma_disciplina']??0);$dia=$_POST['dia_semana']??'';$inicio=$_POST['hora_inicio']??'';$fim=$_POST['hora_fim']??'';
        if($vinculo>0&&in_array($dia,['Segunda','Terça','Quarta','Quinta','Sexta'],true)&&$inicio!==''&&$fim!==''){$stmt=$conexao->prepare('INSERT INTO horario(id_turma_disciplina,dia_semana,hora_inicio,hora_fim) VALUES(?,?,?,?)');$stmt->bind_param('isss',$vinculo,$dia,$inicio,$fim);$ok=$stmt->execute();$stmt->close();$mensagem=$ok?'<div class="sucesso">Horário criado com sucesso.</div>':'<div class="erro">Não foi possível criar o horário.</div>';}
    }
}

$professores=[];$result=$conexao->query("SELECT id_usuario,nome FROM usuario WHERE perfil='Professor' AND ativo=1 ORDER BY nome");while($row=$result->fetch_assoc()){$professores[]=$row;}
$disciplinas=[];$result=$conexao->query('SELECT id_disciplina,nome FROM disciplina ORDER BY nome');while($row=$result->fetch_assoc()){$disciplinas[]=$row;}
$turmas=[];$result=$conexao->query('SELECT id_turma,nome,ano_letivo,periodo FROM turma ORDER BY nome');while($row=$result->fetch_assoc()){$turmas[]=$row;}
$vinculos=[];$result=$conexao->query('SELECT td.id_turma_disciplina,t.nome AS turma_nome,d.nome AS disciplina_nome,u.nome AS professor_nome FROM turma_disciplina td JOIN turma t ON t.id_turma=td.id_turma JOIN disciplina d ON d.id_disciplina=td.id_disciplina JOIN usuario u ON u.id_usuario=td.id_professor ORDER BY t.nome,d.nome');while($row=$result->fetch_assoc()){$vinculos[]=$row;}
$professor_vinculos=[];$result=$conexao->query('SELECT pd.id_professor_disciplina,u.nome AS professor_nome,d.nome AS disciplina_nome FROM professor_disciplina pd JOIN usuario u ON u.id_usuario=pd.id_professor JOIN disciplina d ON d.id_disciplina=pd.id_disciplina ORDER BY u.nome,d.nome');while($row=$result->fetch_assoc()){$professor_vinculos[]=$row;}
$horarios=[];$result=$conexao->query("SELECT h.id_horario,h.dia_semana,h.hora_inicio,h.hora_fim,t.nome AS turma_nome,d.nome AS disciplina_nome,u.nome AS professor_nome FROM horario h JOIN turma_disciplina td ON td.id_turma_disciplina=h.id_turma_disciplina JOIN turma t ON t.id_turma=td.id_turma JOIN disciplina d ON d.id_disciplina=td.id_disciplina JOIN usuario u ON u.id_usuario=td.id_professor ORDER BY t.nome,h.dia_semana,h.hora_inicio");while($row=$result->fetch_assoc()){$horarios[]=$row;}
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Secretaria | Relações</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>*{box-sizing:border-box}body{margin:0;background:#f7f8fc;color:#202338;font-family:Inter,Arial,sans-serif}main{max-width:1230px;margin:0 auto;padding:46px 42px 90px}.header{background:none;color:#202338;border-radius:0;padding:0;margin-bottom:30px}.header:before{content:'INSTITUTO ATLAS / SECRETARIA';display:block;color:#6664df;font-size:11px;letter-spacing:.15em;font-weight:800;margin-bottom:14px}.header h1{margin:0;font-size:clamp(26px,3vw,34px);letter-spacing:-.045em}.tabs{display:flex;gap:9px;flex-wrap:wrap;margin:0 0 22px;padding:5px;background:#edeef6;border-radius:13px;width:max-content;max-width:100%}.tabs a{padding:11px 16px;border-radius:9px;background:transparent;color:#696d82;text-decoration:none;font-size:13px;font-weight:700}.tabs .ativo{background:#fff;color:#5652c7;box-shadow:0 2px 8px #17192712}.panel{background:#fff;border:1px solid #e7e9f1;border-radius:17px;padding:27px 29px;margin-bottom:20px;box-shadow:0 7px 25px #17192705}.panel h2{font-size:18px;letter-spacing:-.035em;color:#25283b;margin:0 0 22px}.panel h2:not(:first-child){padding-top:26px;border-top:1px solid #e7e9f1}.form{display:flex;gap:13px;flex-wrap:wrap;align-items:end;padding-bottom:8px}.campo{display:flex;flex-direction:column;gap:8px;min-width:185px;flex:1}.campo label{font-size:12px;font-weight:700;color:#4e5368}.campo select,.campo input{width:100%;min-height:43px;padding:10px 12px;border:1px solid #dfe2ed;border-radius:9px;background:#fbfcff;color:#292d41;font:inherit;font-size:13px}.campo select:focus,.campo input:focus{outline:2px solid #a6a4ff;outline-offset:1px}.btn{border:0;border-radius:9px;min-height:43px;padding:11px 18px;background:#6664df;color:#fff;font-weight:700;cursor:pointer}.btn:hover{background:#5351c8}.tabela{width:100%;border-collapse:collapse;min-width:640px}.tabela th,.tabela td{padding:15px 12px;border-bottom:1px solid #eceef5;text-align:left;font-size:13px}.tabela th{font-size:10px;letter-spacing:.09em;color:#83889c;text-transform:uppercase;font-weight:800}.tabela tr:last-child td{border-bottom:0}.remover{background:#fff0f1;color:#b43547;border:0;border-radius:8px;padding:9px 12px;cursor:pointer;font-weight:700}.editar{background:#eeedff;color:#5552c3;text-decoration:none;display:inline-block;border-radius:8px;padding:9px 12px;font-weight:700}.sucesso,.erro,.aviso{padding:13px 16px;border-radius:10px;margin-bottom:18px;font-size:13px}.sucesso{background:#e9f7f0;color:#216a48}.erro{background:#fff0f0;color:#a12d3a}.aviso{background:#fff7e9;color:#92610d}.table-wrap{overflow-x:auto} @media(max-width:800px){main{padding:75px 18px 55px}.panel{padding:20px 16px}.tabs{width:100%}.tabs a{flex:1;text-align:center}.campo{min-width:100%}.btn{width:100%}}</style></head><body><?php include '../../includes/menu_secretaria.php';?><main><section class="header"><h1>Relações administrativas</h1></section><nav class="tabs"><?php foreach($tipos as $chave=>$nome):?><a class="<?php echo $tipo===$chave?'ativo':'';?>" href="?tipo=<?php echo $chave;?>"><?php echo $nome;?></a><?php endforeach;?></nav><?php echo $mensagem;?><section class="panel"><?php if($tipo==='professor_disciplina'):?><h2>Vincular professor e disciplina</h2><form class="form" method="POST"><input type="hidden" name="tipo" value="professor_disciplina"><div class="campo"><label>Professor</label><select name="id_professor" required><option value="">Selecione</option><?php foreach($professores as $item):?><option value="<?php echo $item['id_usuario'];?>"><?php echo htmlspecialchars($item['nome']);?></option><?php endforeach;?></select></div><div class="campo"><label>Disciplina</label><select name="id_disciplina" required><option value="">Selecione</option><?php foreach($disciplinas as $item):?><option value="<?php echo $item['id_disciplina'];?>"><?php echo htmlspecialchars($item['nome']);?></option><?php endforeach;?></select></div><button class="btn">Adicionar</button></form><h2 style="margin-top:26px">Vínculos existentes</h2><div class="table-wrap"><table class="tabela"><tr><th>Professor</th><th>Disciplina</th><th>Ação</th></tr><?php foreach($professor_vinculos as $item):?><tr><td><?php echo htmlspecialchars($item['professor_nome']);?></td><td><?php echo htmlspecialchars($item['disciplina_nome']);?></td><td><form method="POST"><input type="hidden" name="tipo" value="professor_disciplina"><input type="hidden" name="id" value="<?php echo $item['id_professor_disciplina'];?>"><button class="remover" name="remover">Remover</button></form></td></tr><?php endforeach;?></table></div>
<?php elseif($tipo==='turma_disciplina'):?><h2>Vincular turma, disciplina e professor</h2><form class="form" method="POST"><input type="hidden" name="tipo" value="turma_disciplina"><div class="campo"><label>Turma</label><select name="id_turma" required><option value="">Selecione</option><?php foreach($turmas as $item):?><option value="<?php echo $item['id_turma'];?>"><?php echo htmlspecialchars($item['nome'].' - '.$item['ano_letivo']);?></option><?php endforeach;?></select></div><div class="campo"><label>Disciplina</label><select name="id_disciplina" required><option value="">Selecione</option><?php foreach($disciplinas as $item):?><option value="<?php echo $item['id_disciplina'];?>"><?php echo htmlspecialchars($item['nome']);?></option><?php endforeach;?></select></div><div class="campo"><label>Professor</label><select name="id_professor" required><option value="">Selecione</option><?php foreach($professores as $item):?><option value="<?php echo $item['id_usuario'];?>"><?php echo htmlspecialchars($item['nome']);?></option><?php endforeach;?></select></div><button class="btn">Adicionar</button></form><h2 style="margin-top:26px">Vínculos existentes</h2><div class="table-wrap"><table class="tabela"><tr><th>Turma</th><th>Disciplina</th><th>Professor</th><th>Ação</th></tr><?php foreach($vinculos as $item):?><tr><td><?php echo htmlspecialchars($item['turma_nome']);?></td><td><?php echo htmlspecialchars($item['disciplina_nome']);?></td><td><?php echo htmlspecialchars($item['professor_nome']);?></td><td><form method="POST"><input type="hidden" name="tipo" value="turma_disciplina"><input type="hidden" name="id" value="<?php echo $item['id_turma_disciplina'];?>"><button class="remover" name="remover">Remover</button></form></td></tr><?php endforeach;?></table></div>
<?php else:?><h2>Cadastrar horário</h2><form class="form" method="POST"><input type="hidden" name="tipo" value="horario"><div class="campo"><label>Turma, disciplina e professor</label><select name="id_turma_disciplina" required><option value="">Selecione</option><?php foreach($vinculos as $item):?><option value="<?php echo $item['id_turma_disciplina'];?>"><?php echo htmlspecialchars($item['turma_nome'].' - '.$item['disciplina_nome'].' - '.$item['professor_nome']);?></option><?php endforeach;?></select></div><div class="campo"><label>Dia</label><select name="dia_semana" required><option>Segunda</option><option>Terça</option><option>Quarta</option><option>Quinta</option><option>Sexta</option></select></div><div class="campo"><label>Início</label><input type="time" name="hora_inicio" required></div><div class="campo"><label>Fim</label><input type="time" name="hora_fim" required></div><button class="btn">Adicionar</button></form><h2 style="margin-top:26px">Horários existentes</h2><div class="table-wrap"><table class="tabela"><tr><th>Turma</th><th>Disciplina</th><th>Professor</th><th>Dia</th><th>Horário</th><th>Ação</th></tr><?php foreach($horarios as $item):?><tr><td><?php echo htmlspecialchars($item['turma_nome']);?></td><td><?php echo htmlspecialchars($item['disciplina_nome']);?></td><td><?php echo htmlspecialchars($item['professor_nome']);?></td><td><?php echo htmlspecialchars($item['dia_semana']);?></td><td><?php echo htmlspecialchars(substr($item['hora_inicio'],0,5).' - '.substr($item['hora_fim'],0,5));?></td><td><form method="POST"><input type="hidden" name="tipo" value="horario"><input type="hidden" name="id" value="<?php echo $item['id_horario'];?>"><button class="remover" name="remover">Remover</button></form></td></tr><?php endforeach;?></table></div><?php endif;?></section></main></body></html>
